if (msg.payload && msg.payload.value === true) {
    return {
        topic: "home/living_room/device/light/command",
        payload: JSON.stringify({
            state: "on",
            source: "presence_automation"
        })
    };
}

return null;

const temperature = msg.payload?.value;

if (typeof temperature !== "number") {
    return null;
}

let requestedState;

if (temperature >= 28) {
    requestedState = "on";
} else if (temperature <= 24) {
    requestedState = "off";
} else {
    return null;
}

// Avoid sending the same command repeatedly.
const lastFanState = context.get("lastFanState");

if (lastFanState === requestedState) {
    return null;
}

context.set("lastFanState", requestedState);

return {
    topic: "home/living_room/device/fan/command",
    payload: JSON.stringify({
        state: requestedState,
        source: "temperature_automation",
        temperature: temperature
    })
};

const topicParts = msg.topic.split("/");

// Expected topic:
// home/{room_id}/sensor/{sensor_type}
if (
    topicParts.length !== 4 ||
    topicParts[0] !== "home" ||
    topicParts[2] !== "sensor"
) {
    return null;
}

const roomId = topicParts[1];
const sensorType = topicParts[3];
const reading = msg.payload;

if (
    !reading ||
    !reading.house_id ||
    !reading.sensor_id ||
    reading.room_id !== roomId ||
    reading.sensor_type !== sensorType ||
    typeof reading.value === "undefined"
) {
    node.warn(`Invalid sensor payload on ${msg.topic}`);
    return null;
}

const numericValue =
    sensorType === "presence"
        ? (reading.value ? 1 : 0)
        : Number(reading.value);

if (Number.isNaN(numericValue)) {
    node.warn(`Invalid sensor value on ${msg.topic}`);
    return null;
}

msg.payload = [
    {
        value: numericValue
    },
    {
        house_id: reading.house_id,
        room: roomId,
        sensor_type: sensorType,
        sensor_id: reading.sensor_id,
        unit: reading.unit || ""
    }
];

return msg;

const topicParts = msg.topic.split("/");

// Expected topic:
// home/{room_id}/device/{device_type}/state
if (
    topicParts.length !== 5 ||
    topicParts[0] !== "home" ||
    topicParts[2] !== "device" ||
    topicParts[4] !== "state"
) {
    return null;
}

const roomId = topicParts[1];
const deviceType = topicParts[3];
const device = msg.payload;

if (
    !device ||
    !device.house_id ||
    !device.device_id ||
    device.room_id !== roomId ||
    device.device_type !== deviceType ||
    !["on", "off"].includes(device.state)
) {
    node.warn(`Invalid device-state payload on ${msg.topic}`);
    return null;
}

msg.payload = [
    {
        is_on: device.state === "on" ? 1 : 0
    },
    {
        house_id: device.house_id,
        room: roomId,
        device_name: deviceType,
        device_type: deviceType,
        device_id: device.device_id
    }
];

return msg;

msg.payload = {
    severity: "warning",
    alert_type: "device_offline",
    message: `Simulator offline: ${msg.topic}`,
    timestamp: new Date().toISOString()
};

return msg;

const alert = msg.payload;
const topicParts = msg.topic.split("/");

msg.payload = [
    {
        message: alert.message
    },
    {
        severity: alert.severity,
        alert_type: alert.alert_type,
        room: topicParts[1]
    }
];

return msg;

const parts = (msg.topic || "").split("/");

if (
    parts.length !== 4 ||
    parts[0] !== "home" ||
    parts[2] !== "sensor" ||
    parts[3] !== "temperature"
) {
    return null;
}

const roomId = parts[1];
const temperature = Number(msg.payload?.value);

if (!Number.isFinite(temperature)) {
    return null;
}

const wasHigh = context.get(`temperatureHigh:${roomId}`) || false;

if (temperature >= 26 && !wasHigh) {
    context.set(`temperatureHigh:${roomId}`, true);

    msg.payload = {
        severity: "warning",
        alert_type: "high_temperature",
        room_id: roomId,
        message: `High temperature in ${roomId}: ${temperature} °C`,
        timestamp: new Date().toISOString()
    };

    return msg;
}

if (temperature <= 23 && wasHigh) {
    context.set(`temperatureHigh:${roomId}`, false);
}

return null;

const topicParts = msg.topic.split("/");

// Ignore home/system/status.
// Keep only home/{room_id}/status.
if (
    topicParts.length !== 3 ||
    topicParts[0] !== "home" ||
    topicParts[2] !== "status"
) {
    return null;
}

const roomId = topicParts[1];
const status = msg.payload;

if (
    roomId === "system" ||
    !status ||
    status.room_id !== roomId ||
    !status.house_id
) {
    return null;
}

const rooms = flow.get("roomCapabilities") || {};

rooms[roomId] = {
    house_id: status.house_id,
    room_name: status.room_name,
    sensor_types: status.sensor_types || [],
    devices: status.devices || [],
    online: status.status === "online",
    updated_at: status.timestamp
};

flow.set("roomCapabilities", rooms);

msg.payload = {
    event: "room_capabilities_cached",
    room_id: roomId,
    room_name: status.room_name,
    devices: status.devices || []
};

return msg;

const parts = (msg.topic || "").split("/");

// Only process: home/{room_id}/sensor/{sensor_type}
if (
    parts.length !== 4 ||
    parts[0] !== "home" ||
    parts[2] !== "sensor"
) {
    return null;
}

const roomId = parts[1];
const sensorType = parts[3];
const reading = msg.payload;

if (
    !reading ||
    !reading.house_id ||
    !reading.sensor_id ||
    reading.room_id !== roomId ||
    reading.sensor_type !== sensorType ||
    reading.value === undefined
) {
    node.warn(`Invalid automation event: ${msg.topic}`);
    return null;
}

// Get capabilities cached by "Cache room capabilities".
const rooms = flow.get("roomCapabilities") || {};
const room = rooms[roomId];

if (
    !room ||
    !room.online ||
    room.house_id !== reading.house_id ||
    !Array.isArray(room.sensor_types) ||
    !room.sensor_types.includes(sensorType)
) {
    return null;
}

let targetType = null;
let desiredState = null;

// Rule 1: Presence -> Light ON
if (sensorType === "presence") {
    if (reading.value === true) {
        targetType = "light";
        desiredState = "on";
    }
}

// Rule 2: Temperature -> Fan
else if (sensorType === "temperature") {
    const temperature = Number(reading.value);

    if (!Number.isFinite(temperature)) {
        return null;
    }

    if (temperature >= 28) {
        targetType = "fan";
        desiredState = "on";
    } else if (temperature <= 24) {
        targetType = "fan";
        desiredState = "off";
    }
}

if (!targetType || !desiredState) {
    return null;
}

// Find the device in this room only.
const targetDevice = room.devices.find(
    device => device.type === targetType
);

if (!targetDevice) {
    return null;
}

// Avoid repeating an identical command.
const commandKey = `${roomId}:${targetDevice.id}`;
const lastCommands = context.get("lastCommands") || {};

if (lastCommands[commandKey] === desiredState) {
    return null;
}

lastCommands[commandKey] = desiredState;
context.set("lastCommands", lastCommands);

// Send a command to the simulator through MQTT.
msg.topic = `home/${roomId}/device/${targetType}/command`;

msg.payload = JSON.stringify({
    house_id: room.house_id,
    room_id: roomId,
    device_id: targetDevice.id,
    device_type: targetType,
    state: desiredState,
    source: "node-red-automation",
    timestamp: new Date().toISOString()
});

return msg;
